import java.util.*;

public class Main {
    record Task(int id, String title, boolean done) {}

    static class TaskManager {
        private final List<Task> tasks = new ArrayList<>();
        private int next = 1;

        Task add(String title) {
            Task t = new Task(next++, title, false);
            tasks.add(t);
            return t;
        }

        void complete(int id) {
            for (int i = 0; i < tasks.size(); i++) {
                Task t = tasks.get(i);
                if (t.id() == id) {
                    tasks.set(i, new Task(t.id(), t.title(), true));
                    return;
                }
            }
            throw new NoSuchElementException("No task " + id);
        }

        List<Task> pending() {
            List<Task> r = new ArrayList<>();
            for (Task t : tasks) if (!t.done()) r.add(t);
            return r;
        }
    }

    public static void main(String[] args) {
        TaskManager m = new TaskManager();
        m.add("Learn Java");
        m.add("Build project");
        m.complete(1);
        System.out.println(m.pending().size());
        try { m.complete(99); } catch (NoSuchElementException e) { System.out.println(e.getMessage()); }
    }
}

